import { Component, OnInit } from '@angular/core';
import { MarketOverviewService, SecurityPerformance } from '../market-overview.service';
import { forkJoin } from 'rxjs';

@Component({
  selector: 'app-top-performers',
  templateUrl: './top-performers.component.html',
  styleUrls: ['./top-performers.component.css']
})
export class TopPerformersComponent implements OnInit {
  topGainers: SecurityPerformance[] = [];
  topLosers: SecurityPerformance[] = [];
  mostTraded: SecurityPerformance[] = [];
  loading = true;
  count = 5;

  constructor(private marketOverviewService: MarketOverviewService) { }

  ngOnInit() {
    forkJoin({
      gainers: this.marketOverviewService.getTopGainers(this.count),
      losers: this.marketOverviewService.getTopLosers(this.count),
      traded: this.marketOverviewService.getMostTraded(this.count),
    }).subscribe({
      next: ({ gainers, losers, traded }) => {
        this.topGainers = gainers ?? [];
        this.topLosers = losers ?? [];
        this.mostTraded = traded ?? [];
      },
      error: (err) => console.error('Error loading top performers', err),
      complete: () => (this.loading = false)
    });
  }
}
<div class="top-performers" *ngIf="!loading">
  <div class="performer-table">
    <h4><i class="bi bi-graph-up-arrow text-success"></i> Top Gainers</h4>
    <table>
      <thead>
        <tr><th>Code</th><th>% Change</th></tr>
      </thead>
      <tbody>
        <tr *ngFor="let s of topGainers">
          <td>{{ s.code }}</td>
          <td class="positive">+{{ s.changePercent | number:'1.2-2' }}%</td>
        </tr>
      </tbody>
    </table>
  </div>

  <div class="performer-table">
    <h4><i class="bi bi-graph-down-arrow text-danger"></i> Top Losers</h4>
    <table>
      <thead>
        <tr><th>Code</th><th>% Change</th></tr>
      </thead>
      <tbody>
        <tr *ngFor="let s of topLosers">
          <td>{{ s.code }}</td>
          <td class="negative">{{ s.changePercent | number:'1.2-2' }}%</td>
        </tr>
      </tbody>
    </table>
  </div>

  <div class="performer-table">
    <h4><i class="bi bi-cash-coin text-warning"></i> Most Traded</h4>
    <table>
      <thead>
        <tr><th>Code</th><th>Volume</th></tr>
      </thead>
      <tbody>
        <tr *ngFor="let s of mostTraded">
          <td>{{ s.code }}</td>
          <td>{{ s.volume | number }}</td>
        </tr>
      </tbody>
    </table>
  </div>
</div>

<div *ngIf="loading" class="loading">Loading performance data...</div>
